--- clean/crates/crypto/circuits/src/hash/inspection.rs
+++ overlay/crates/crypto/circuits/src/hash/inspection.rs
@@ -0,0 +1,133 @@
+//! Read-only existing permutation boundaries for RNK and its commitment.
+use super::Scalar;
+use crate::scalar::inspection::Observed;
+use commonware_cryptography::zk::circuit::Var;
+use std::{cell::RefCell,marker::PhantomData,rc::Rc};
+
+/// `before` is the permutation input AFTER absorption, not a pre-absorb state.
+#[derive(Clone,PartialEq,Eq)]
+pub struct Block { pub before: Vec<Observed>, pub after: Vec<Observed> }
+#[derive(Clone,PartialEq,Eq)]
+pub struct Report {
+    pub domain: u8,
+    pub inputs: Vec<Observed>,
+    pub output: Observed,
+    pub blocks: Vec<Block>,
+}
+#[derive(Default)]
+struct State { reports: Vec<Report>, pending: Option<Pending>, invalid: bool, taken: bool }
+struct Pending { domain: u8, inputs: Vec<Observed>, blocks: Vec<Block>, before: Option<Vec<Observed>> }
+thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+pub struct Capture { _thread: PhantomData<Rc<()>> }
+impl Drop for Capture { fn drop(&mut self) { STATE.with(|state| *state.borrow_mut()=None); } }
+pub fn begin() -> anyhow::Result<Capture> {
+    STATE.with(|state| {
+        anyhow::ensure!(state.borrow().is_none(),"hash observation session already active");
+        *state.borrow_mut()=Some(State::default());
+        Ok(Capture { _thread: PhantomData })
+    })
+}
+pub struct Call { active: bool, _thread: PhantomData<Rc<()>> }
+fn observed(value: &Var<'_,Scalar>) -> Observed {
+    match value.inspect_circuit_idx() {
+        Some(index)=>Observed::Source(index),
+        None=>Observed::Native(value.inspect_native().expect("invalid hash variable").clone()),
+    }
+}
+pub(super) fn start(domain: u8, inputs: &[Var<'_,Scalar>]) -> Call {
+    let active=STATE.with(|state| {
+        let mut state=state.borrow_mut();
+        let Some(state)=state.as_mut() else { return false; };
+        if domain!=17 && domain!=18 { return false; }
+        if state.taken || state.pending.is_some() || state.reports.len()>=2 ||
+            (domain==17 && inputs.len()!=9) || (domain==18 && inputs.len()!=1) {
+            state.invalid=true; return false;
+        }
+        state.pending=Some(Pending {domain,inputs:inputs.iter().map(observed).collect(),
+            blocks:Vec::new(),before:None});
+        true
+    });
+    Call { active,_thread:PhantomData }
+}
+pub(super) fn state(call: &Call, index: usize, after: bool, values: &[Var<'_,Scalar>]) {
+    if !call.active { return; }
+    STATE.with(|state| {
+        let mut state=state.borrow_mut();let Some(state)=state.as_mut() else { return; };
+        let Some(pending)=state.pending.as_mut() else { state.invalid=true;return; };
+        let width=if pending.domain==17 {6} else {3};
+        let count=if pending.domain==17 {2} else {1};
+        if values.len()!=width || index!=pending.blocks.len() || index>=count {
+            state.invalid=true;return;
+        }
+        if after {
+            let Some(before)=pending.before.take() else {state.invalid=true;return;};
+            pending.blocks.push(Block {before,after:values.iter().map(observed).collect()});
+        } else if pending.before.is_some() { state.invalid=true; }
+        else {pending.before=Some(values.iter().map(observed).collect());}
+    });
+}
+pub(super) fn finish(call: Call, output: &Var<'_,Scalar>) {
+    if !call.active {return;}
+    STATE.with(|state| {
+        let mut state=state.borrow_mut();let Some(state)=state.as_mut() else{return;};
+        let Some(pending)=state.pending.take() else {state.invalid=true;return;};
+        let count=if pending.domain==17 {2} else {1};
+        if pending.before.is_some() || pending.blocks.len()!=count {state.invalid=true;return;}
+        state.reports.push(Report {domain:pending.domain,inputs:pending.inputs,
+            output:observed(output),blocks:pending.blocks});
+    });
+}
+pub fn take() -> anyhow::Result<Vec<Report>> {
+    STATE.with(|state| {
+        let mut state=state.borrow_mut();let state=state.as_mut().ok_or_else(||anyhow::anyhow!("no hash observation session"))?;
+        anyhow::ensure!(!state.taken && !state.invalid && state.pending.is_none() && state.reports.len()==2,
+            "incomplete RNK/commitment hash observation");
+        anyhow::ensure!(state.reports[0].domain==17 && state.reports[1].domain==18,
+            "RNK/commitment hash order changed");
+        state.taken=true;
+        Ok(std::mem::take(&mut state.reports))
+    })
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+    fn values(count: usize) -> Vec<Var<'static,Scalar>> {
+        (0..count).map(|index|Var::native(Scalar::from(index as u64+1))).collect()
+    }
+    fn complete() {
+        let wide=values(6);let small=values(3);
+        let call=start(17,&values(9));assert!(call.active);
+        for index in 0..2 {state(&call,index,false,&wide);state(&call,index,true,&wide);}
+        finish(call,&wide[1]);
+        let call=start(18,&values(1));assert!(call.active);
+        state(&call,0,false,&small);state(&call,0,true,&small);finish(call,&small[1]);
+    }
+    #[test]
+    fn session_bounds_isolation_and_panic_cleanup() {
+        assert!(!start(17,&values(9)).active);
+        {
+            let _capture=begin().unwrap();assert!(begin().is_err());
+            assert!(!start(16,&values(3)).active);
+            complete();let reports=take().unwrap();
+            assert_eq!(reports.len(),2);assert_eq!(reports[0].blocks.len(),2);
+            assert_eq!(reports[1].blocks.len(),1);assert!(take().is_err());
+        }
+        {
+            let _capture=begin().unwrap();complete();
+            assert!(!start(17,&values(9)).active);assert!(take().is_err());
+        }
+        {
+            let _capture=begin().unwrap();assert!(!start(17,&values(1)).active);
+            assert!(take().is_err());
+        }
+        {
+            let _capture=begin().unwrap();let call=start(17,&values(9));
+            state(&call,0,true,&values(6));finish(call,&values(1)[0]);assert!(take().is_err());
+        }
+        let panicked=std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
+            let _capture=begin().unwrap();let _call=start(17,&values(9));panic!("test cleanup");
+        }));
+        assert!(panicked.is_err());let _capture=begin().unwrap();complete();assert!(take().is_ok());
+    }
+}
